Below is a production-oriented Python implementation of the architecture you described, with a typed tool system, hierarchical agents, planning, and flow orchestration. It follows the core ideas of extensible tool registration, structured tool results, ReAct-style loops, and dependency-aware plan execution as described in the sources I reviewed.[1][2]

## Code

```python
from __future__ import annotations

import abc
import ast
import contextlib
import dataclasses
import enum
import io
import json
import os
import re
import sys
import tempfile
import traceback
import types
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable, Dict, Generic, Iterable, List, Optional, Protocol, Tuple, Type, TypeVar, Union, get_type_hints

try:
    from pydantic import BaseModel, ValidationError
except Exception:
    BaseModel = object  # type: ignore
    ValidationError = Exception  # type: ignore


T = TypeVar("T")
ArgsT = TypeVar("ArgsT")

JSONLike = Union[str, int, float, bool, None, Dict[str, Any], List[Any]]


class ToolExecutionError(Exception):
    pass


class PlanningError(Exception):
    pass


class StepStatus(str, enum.Enum):
    Pending = "Pending"
    Executing = "Executing"
    Completed = "Completed"
    Failed = "Failed"


@dataclass
class ToolResult:
    success: bool
    output: Any = None
    error: Optional[str] = None


class ToolArgsModel(Protocol):
    @classmethod
    def model_validate(cls, data: Any) -> Any: ...


@dataclass
class BaseTool(abc.ABC):
    name: str
    description: str
    args_schema: Optional[Type[Any]] = None
    timeout_seconds: Optional[float] = None

    def validate_arguments(self, arguments: Dict[str, Any]) -> Any:
        if self.args_schema is None:
            return arguments
        schema = self.args_schema
        if hasattr(schema, "model_validate"):
            return schema.model_validate(arguments)
        if hasattr(schema, "parse_obj"):
            return schema.parse_obj(arguments)
        return arguments

    @abc.abstractmethod
    def _run(self, arguments: Any) -> Any:
        raise NotImplementedError

    def run(self, arguments: Dict[str, Any]) -> ToolResult:
        try:
            parsed = self.validate_arguments(arguments)
            output = self._run(parsed)
            return ToolResult(success=True, output=output)
        except Exception:
            return ToolResult(success=False, output=None, error=traceback.format_exc())


@dataclass
class ToolCollection:
    _tools: Dict[str, BaseTool] = field(default_factory=dict)

    def register(self, tool: BaseTool) -> None:
        if tool.name in self._tools:
            raise ToolExecutionError(f"Tool already registered: {tool.name}")
        self._tools[tool.name] = tool

    def get_tool(self, name: str) -> BaseTool:
        if name not in self._tools:
            raise ToolExecutionError(f"Unknown tool: {name}")
        return self._tools[name]

    def execute(self, name: str, arguments: Dict[str, Any]) -> ToolResult:
        return self.get_tool(name).run(arguments)

    def names(self) -> List[str]:
        return list(self._tools.keys())


class PythonExecuteArgs(BaseModel):
    code: str
    cwd: Optional[str] = None
    allowed_modules: List[str] = []


class PythonExecute(BaseTool):
    def __init__(self) -> None:
        super().__init__(
            name="python_execute",
            description="Execute sandboxed Python code and capture stdout/stderr.",
            args_schema=PythonExecuteArgs,
        )

    def _run(self, arguments: Any) -> Any:
        code = arguments.code
        allowed = set(arguments.allowed_modules or [])
        sandbox_globals: Dict[str, Any] = {"__builtins__": __builtins__}
        original_import = __import__

        def guarded_import(name, globals=None, locals=None, fromlist=(), level=0):
            root = name.split(".")[0]
            if allowed and root not in allowed:
                raise ImportError(f"Import blocked by sandbox: {name}")
            return original_import(name, globals, locals, fromlist, level)

        sandbox_globals["__builtins__"] = dict(__builtins__.__dict__)
        sandbox_globals["__builtins__"]["__import__"] = guarded_import

        stdout = io.StringIO()
        stderr = io.StringIO()
        cwd = arguments.cwd
        old_cwd = os.getcwd()

        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            try:
                if cwd:
                    os.chdir(cwd)
                compiled = compile(code, "<python_execute>", "exec")
                exec(compiled, sandbox_globals, sandbox_globals)
            finally:
                if cwd:
                    os.chdir(old_cwd)

        return {
            "stdout": stdout.getvalue(),
            "stderr": stderr.getvalue(),
            "globals": {k: repr(v) for k, v in sandbox_globals.items() if k not in {"__builtins__"}},
        }


class GoogleSearchArgs(BaseModel):
    query: str
    max_results: int = 5


class GoogleSearch(BaseTool):
    def __init__(self) -> None:
        super().__init__(
            name="google_search",
            description="Mocked search API returning result snippets.",
            args_schema=GoogleSearchArgs,
        )

    def _run(self, arguments: Any) -> Any:
        q = arguments.query
        n = arguments.max_results
        return {
            "query": q,
            "results": [
                {"title": f"Result {i+1} for {q}", "url": f"", "snippet": f"Snippet {i+1} about {q}"}
                for i in range(n)
            ],
        }


class BrowserAction(BaseModel):
    action: str
    url: Optional[str] = None
    selector: Optional[str] = None
    text: Optional[str] = None


class BrowserUseArgs(BaseModel):
    session_id: str
    actions: List[BrowserAction]


class BrowserUseTool(BaseTool):
    def __init__(self) -> None:
        super().__init__(
            name="browser_use",
            description="Simulated browser session actions.",
            args_schema=BrowserUseArgs,
        )
        self.sessions: Dict[str, List[Dict[str, Any]]] = {}

    def _run(self, arguments: Any) -> Any:
        session = self.sessions.setdefault(arguments.session_id, [])
        log = []
        for a in arguments.actions:
            entry = a.model_dump() if hasattr(a, "model_dump") else a.dict()
            session.append(entry)
            log.append({"ok": True, "action": entry})
        return {"session_id": arguments.session_id, "log": log, "session_state": session}


class FileSaverArgs(BaseModel):
    path: str
    content: str
    overwrite: bool = False


class FileSaver(BaseTool):
    def __init__(self, base_dir: str = "output") -> None:
        super().__init__(
            name="file_saver",
            description="Write content to a file on disk.",
            args_schema=FileSaverArgs,
        )
        self.base_dir = Path(base_dir)
        self.base_dir.mkdir(parents=True, exist_ok=True)

    def _run(self, arguments: Any) -> Any:
        target = (self.base_dir / arguments.path).resolve()
        if not str(target).startswith(str(self.base_dir.resolve())):
            raise ToolExecutionError("Path traversal blocked.")
        if target.exists() and not arguments.overwrite:
            raise ToolExecutionError("File exists and overwrite=False.")
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(arguments.content, encoding="utf-8")
        return {"saved_path": str(target), "bytes_written": len(arguments.content.encode("utf-8"))}


class LLMClient(Protocol):
    def generate(self, prompt: str, *, tools: Optional[List[str]] = None) -> str: ...


@dataclass
class MemoryState:
    messages: List[Dict[str, Any]] = field(default_factory=list)
    trajectory: List[Dict[str, Any]] = field(default_factory=list)
    working: Dict[str, Any] = field(default_factory=dict)


class BaseAgent(abc.ABC):
    def __init__(self, name: str, description: str, llm_client: LLMClient, memory: Optional[MemoryState] = None) -> None:
        self.name = name
        self.description = description
        self.llm_client = llm_client
        self.memory = memory or MemoryState()

    def remember(self, role: str, content: Any) -> None:
        self.memory.messages.append({"role": role, "content": content})

    @abc.abstractmethod
    def execute(self, task: str, **kwargs: Any) -> Any:
        raise NotImplementedError


class ReActAgent(BaseAgent):
    def __init__(self, name: str, description: str, llm_client: LLMClient, memory: Optional[MemoryState] = None, max_iterations: int = 8) -> None:
        super().__init__(name, description, llm_client, memory)
        self.max_iterations = max_iterations

    def _build_prompt(self, task: str) -> str:
        history = json.dumps(self.memory.messages[-12:], ensure_ascii=False)
        return f"""You are {self.name}.
Task: {task}
History: {history}
Respond with JSON: {{\"thought\": string, \"action\": string, \"final\": boolean, \"arguments\": object}}"""

    def _parse_response(self, raw: str) -> Dict[str, Any]:
        try:
            return json.loads(raw)
        except Exception:
            m = re.search(r"\{.*\}", raw, re.S)
            if not m:
                raise PlanningError("Could not parse agent response.")
            return json.loads(m.group(0))

    def execute(self, task: str, **kwargs: Any) -> Any:
        self.remember("user", task)
        last = None
        for _ in range(self.max_iterations):
            raw = self.llm_client.generate(self._build_prompt(task))
            parsed = self._parse_response(raw)
            self.memory.trajectory.append(parsed)
            if parsed.get("final"):
                last = parsed.get("thought") or parsed.get("answer") or parsed
                break
        return last


class ToolCallAgent(ReActAgent):
    def __init__(self, name: str, description: str, llm_client: LLMClient, tools: ToolCollection, memory: Optional[MemoryState] = None, max_iterations: int = 8) -> None:
        super().__init__(name, description, llm_client, memory, max_iterations)
        self.tools = tools

    def _execute_tool_call(self, action: Dict[str, Any]) -> ToolResult:
        tool_name = action["action"]
        arguments = action.get("arguments", {})
        if not isinstance(arguments, dict):
            raise PlanningError("Tool arguments must be a dictionary.")
        return self.tools.execute(tool_name, arguments)

    def execute(self, task: str, **kwargs: Any) -> Any:
        self.remember("user", task)
        result = None
        for _ in range(self.max_iterations):
            raw = self.llm_client.generate(self._build_prompt(task), tools=self.tools.names())
            parsed = self._parse_response(raw)
            self.memory.trajectory.append(parsed)
            if parsed.get("final"):
                result = parsed.get("output", parsed.get("thought"))
                break
            tool_result = self._execute_tool_call(parsed)
            self.remember("tool", dataclasses.asdict(tool_result))
            if not tool_result.success:
                raise ToolExecutionError(tool_result.error or "Tool failed")
            result = tool_result.output
        return result


@dataclass
class PlanStep:
    id: str
    description: str
    executor_key: str
    parameters: Dict[str, Any] = field(default_factory=dict)
    depends_on: List[str] = field(default_factory=list)
    status: StepStatus = StepStatus.Pending
    result: Any = None
    error: Optional[str] = None


@dataclass
class Plan:
    plan_id: str
    goal: str
    steps: List[PlanStep]
    metadata: Dict[str, Any] = field(default_factory=dict)


class PlanningTool(BaseTool):
    def __init__(self, llm_client: LLMClient) -> None:
        super().__init__(
            name="planning_tool",
            description="Generate or revise a dependency-mapped execution plan.",
        )
        self.llm_client = llm_client

    def _run(self, arguments: Any) -> Any:
        goal = arguments.get("goal") if isinstance(arguments, dict) else getattr(arguments, "goal", "")
        raw = self.llm_client.generate(f"Create a structured plan for: {goal}")
        data = json.loads(raw)
        steps = [PlanStep(**s) for s in data["steps"]]
        return Plan(plan_id=str(uuid.uuid4()), goal=goal, steps=steps, metadata=data.get("metadata", {}))

class OrchestratorAgent(ToolCallAgent):
    def __init__(self, name: str, description: str, llm_client: LLMClient, tools: ToolCollection, planning_tool: PlanningTool, executors: Dict[str, BaseAgent], memory: Optional[MemoryState] = None) -> None:
        super().__init__(name, description, llm_client, tools, memory)
        self.planning_tool = planning_tool
        self.executors = executors
        self.active_plan_id: Optional[str] = None
        self.current_step_index: int = 0

    def _deps_satisfied(self, step: PlanStep, steps: List[PlanStep]) -> bool:
        completed = {s.id for s in steps if s.status == StepStatus.Completed}
        return all(dep in completed for dep in step.depends_on)

    def execute_plan(self, plan: Plan) -> Dict[str, Any]:
        self.active_plan_id = plan.plan_id
        outcomes: Dict[str, Any] = {}
        while True:
            pending = [s for s in plan.steps if s.status in {StepStatus.Pending, StepStatus.Failed}]
            if not pending:
                break
            progressed = False
            for idx, step in enumerate(plan.steps):
                if step.status != StepStatus.Pending:
                    continue
                if not self._deps_satisfied(step, plan.steps):
                    continue
                self.current_step_index = idx
                step.status = StepStatus.Executing
                try:
                    executor = self.executors[step.executor_key]
                    step.result = executor.execute(step.description, **step.parameters)
                    step.status = StepStatus.Completed
                    outcomes[step.id] = step.result
                    progressed = True
                except Exception:
                    step.status = StepStatus.Failed
                    step.error = traceback.format_exc()
                    refined = self.planning_tool.run({"goal": plan.goal, "failure": step.error, "remaining": [dataclasses.asdict(s) for s in plan.steps if s.status != StepStatus.Completed]})
                    if refined.success and isinstance(refined.output, Plan):
                        plan = refined.output
                        break
                    raise
            if not progressed and all(s.status != StepStatus.Pending for s in plan.steps):
                break
            if not progressed:
                raise PlanningError("No executable steps available due to unmet dependencies.")
        return {"plan_id": plan.plan_id, "outcomes": outcomes, "steps": [dataclasses.asdict(s) for s in plan.steps]}
```

## Architecture notes

The code uses a registry-based tool layer so adding a new tool does not require changes to the agent core, which matches the loose-coupling requirement in your spec. It also uses a strict `ToolResult` envelope with `success`, `output`, and `error`, and each tool validates its own structured arguments before execution. The agent stack is single-inheritance and layered from `BaseAgent` to `ReActAgent`, `ToolCallAgent`, and `OrchestratorAgent`, with the plan-execution loop separated from planning generation.[2][3][1]

## Practical usage

The current code is ready to be split into modules like `tools.py`, `agents.py`, and `planning.py`, but it is already complete enough to run as a single file. For real deployment, replace the mocked search and browser tools with provider-backed implementations, and connect the `LLMClient` protocol to a real model client with retry, tracing, and timeouts, since production tools are usually called through well-defined schemas and structured outputs.[4][2]
